import{_ as a,o as t,c as r,ag as s}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse(`{"title":"0041 — Takoform's Form Packages publish with the provider release that embeds them","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0041-form-packages-publish-with-the-provider-release.md","filePath":"spec/decisions/0041-form-packages-publish-with-the-provider-release.md"}`),o={name:"spec/decisions/0041-form-packages-publish-with-the-provider-release.md"};function i(n,e,d,h,c,l){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="_0041-—-takoform-s-form-packages-publish-with-the-provider-release-that-embeds-them" tabindex="-1">0041 — Takoform&#39;s Form Packages publish with the provider release that embeds them <a class="header-anchor" href="#_0041-—-takoform-s-form-packages-publish-with-the-provider-release-that-embeds-them" aria-label="Permalink to &quot;0041 — Takoform&#39;s Form Packages publish with the provider release that embeds them&quot;">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-08-22</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The question was whether the package axis should be merged into the provider&#39;s. Measured, most of the merge has already happened, one release at a time:</p><ul><li><strong>A package has no version of its own to merge.</strong> Content-addressed packages carry no SemVer — the package digest is the whole identity (<a href="./../versioning.html"><code>../versioning.md</code></a>) — and the envelope is a manifest format tag, not an axis (<a href="./0040-the-package-envelope-is-a-format-not-an-axis.html">decision 0040</a>).</li><li><strong>The provider release already fixes the package set.</strong><a href="../../release/provider-form-identities.json"><code>../../release/provider-form-identities.json</code></a> locks, append-only, the exact <code>packageDigest</code> of every Form a provider release embeds, and the release gate asserts that embedded set byte-equals the candidate set. Provider <code>v2.1.1</code> names all fifteen Beta package digests.</li><li><strong>The provider release is the only vehicle that has ever shipped a current Form contract.</strong> No v1alpha2 or Beta Form Package was ever published independently; the thirty-four independently published packages are the Legacy v1alpha1 epoch, retained as history. In the v1beta1 architecture a Form change requires a provider release anyway — the typed resources and codecs are compiled in, and a build fails closed on a ref it does not carry — so Forms already ride the provider train whether or not packages do.</li></ul><p>So the repository maintains an independent package release channel that the current epoch has never used, for artifacts whose exact digests every provider release already locks.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Takoform publishes its own Form Packages with the provider release that embeds them. There is no independent package release cadence.</strong> One release event: the provider ships, and the package artifacts it locked ship with it, under the digests <code>provider-form-identities.json</code> already records. The publication blockers continue to gate whether that happens at all; this decides only that when it happens, it is not a second train.</p><p><strong>What is deliberately not merged is identity.</strong> A package digest contains no provider version and never will: the Stable criteria in <a href="./../project-lifecycle.html"><code>../project-lifecycle.md</code></a> require packages published by a party other than a consuming host, and a third party publishing under its own cadence needs exactly the provider-independent, content-addressed identity packages already have. The release <em>train</em> is Takoform&#39;s own and merges; the <em>identity</em> is the ecosystem&#39;s and does not.</p><p>The standing rule that axis numbers are never aligned is untouched — nothing here renumbers anything. A cadence is not a number.</p><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to &quot;Enforcement&quot;">​</a></h2><p>Already standing, cited rather than rebuilt: <code>provider-form-identities.json</code> is append-only and digest-frozen per release, and the release gate refuses a provider candidate whose embedded Form and package identities are not byte-equal to the candidate set. Those two checks are precisely &quot;the packages a release ships are the packages the provider embeds&quot;, which is this decision.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>The version axes a user holds stay the three that <a href="./0040-the-package-envelope-is-a-format-not-an-axis.html">decision 0040</a> named — Host API lane, Form contract, provider SemVer — and the maintainer&#39;s release axes shrink from two trains to one. <code>form-package-release</code> tooling remains the mechanism that builds and signs package artifacts; it runs as a step of the provider release when the blockers clear, not as a channel of its own.</p><p>A third-party publisher is unaffected and was the point of the carve-out: the envelope format is open, the identity is content-addressed, and nothing in a package says which provider release, if any, it rode.</p>',15)])])}const g=a(o,[["render",i]]);export{m as __pageData,g as default};
